CREATE OR REPLACE FUNCTION public.fn_get_child_attendance_for_date(p_child_id uuid, p_date date)  RETURNS TABLE(id uuid, tenant_id uuid, branch_id uuid, classroom_id uuid, child_id uuid, attendance_date date, status character varying, arrival_time time without time zone, departure_time time without time zone, notes text, recorded_by_user_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone, pickup_person_name character varying, pickup_person_relationship character varying, pickup_verification_method character varying, pickup_notes text, authorized_pickup_id uuid, departure_verified_by_user_id uuid)  LANGUAGE sql  STABLE AS $function$     SELECT          ca.id,         ca.tenant_id,         ca.branch_id,         ca.classroom_id,         ca.child_id,         ca.attendance_date,         ca.status,         ca.arrival_time,         ca.departure_time,         ca.notes,         ca.recorded_by_user_id,         ca.created_at,         ca.updated_at,         ca.pickup_person_name,         ca.pickup_person_relationship,         ca.pickup_verification_method,         ca.pickup_notes,         ca.authorized_pickup_id,         ca.departure_verified_by_user_id     FROM child_attendance ca     WHERE ca.child_id = p_child_id AND ca.attendance_date = p_date     LIMIT 1; $function$ ;
